#!/usr/bin/env bash
set -euo pipefail

config_file=/etc/default/ruvio-scenario-lab-firewall
if [[ ! -r "$config_file" ]]; then
  echo "Missing $config_file; install the filter with install-docker-ingress-filter.sh." >&2
  exit 1
fi

# The config file is root-owned and generated by the installer from validated values.
source "$config_file"

chain=RUVIO_SCENARIO_LAB
iptables=(iptables -w)
peer_interface="$(ip -4 route get "$LAB_PEER_IP" |
  awk '{ for (i = 1; i <= NF; i++) if ($i == "dev") { print $(i + 1); exit } }')"
if [[ -z "$peer_interface" ]]; then
  echo "Could not determine the interface used to reach peer $LAB_PEER_IP." >&2
  exit 1
fi

case "$LAB_ROLE" in
  sut)
    ports=(8080 8474)
    if [[ -n "${LAB_RUVIO_UI_IP:-}" ]]; then
      ports+=(6379)
    fi
    ;;
  observer)
    ports=(4317)
    if [[ -n "${LAB_GRAFANA_IP:-}" ]]; then
      ports+=(3000)
    fi
    ;;
  *)
    echo "Invalid LAB_ROLE in $config_file." >&2
    exit 1
    ;;
esac

if ! "${iptables[@]}" -nL DOCKER-USER >/dev/null 2>&1; then
  echo "Docker DOCKER-USER chain is unavailable; ensure Docker is running." >&2
  exit 1
fi

"${iptables[@]}" -N "$chain" 2>/dev/null || true
"${iptables[@]}" -F "$chain"
for port in "${ports[@]}"; do
  allowed_peer="$LAB_PEER_IP"
  if [[ "$port" == 6379 && -n "${LAB_RUVIO_UI_IP:-}" ]]; then
    allowed_peer="$LAB_RUVIO_UI_IP"
  elif [[ "$port" == 3000 && -n "${LAB_GRAFANA_IP:-}" ]]; then
    allowed_peer="$LAB_GRAFANA_IP"
  fi
  "${iptables[@]}" -A "$chain" -i "$peer_interface" -p tcp -s "$allowed_peer/32" \
    -m conntrack --ctorigdstport "$port" -j ACCEPT
  "${iptables[@]}" -A "$chain" -i "$peer_interface" -p tcp \
    -m conntrack --ctorigdstport "$port" -j DROP
done
"${iptables[@]}" -A "$chain" -j RETURN

if ! "${iptables[@]}" -C DOCKER-USER -j "$chain" 2>/dev/null; then
  "${iptables[@]}" -I DOCKER-USER 1 -j "$chain"
fi

echo "Docker ingress filter active for role=$LAB_ROLE peer=$LAB_PEER_IP interface=$peer_interface."
